  "premises_address": "Room 2202 and Room 2206, 22/F, No. 18 Building, Jianwai SOHO, No. 39, Dong San Huan Middle Road, Chaoyang, Beijing",
  "area": null,
  "start_date": "2009-08-11",
  "end_date": "2011-08-10",
